insert into public.city_rules(city,vehicle,allowed_space_types,conditional_space_types,fee_note,exceptions,effective_date,source_url,version,can_use_two_spaces,districts) values('臺北市','heavy','["paidMotorcycle", "heavyOnly", "car"]'::jsonb,'["offStreet"]'::jsonb,'一般計次每次 40 元；一般計時每小時 20 元，當日上限 100 元；特殊路段另依公告。','僅公有路邊收費機車格；免費巷弄格不適用。可斜停兩格，勿阻礙通行。','2026-10-06','https://www.gov.taipei/News_Content.aspx?n=D0042A87C2F0270A&s=1190C312983454BA&sms=78D644F2755ACCAA',1,true,'[]'::jsonb) on conflict(city,vehicle) do nothing;
insert into public.city_rules(city,vehicle,allowed_space_types,conditional_space_types,fee_note,exceptions,effective_date,source_url,version,can_use_two_spaces,districts) values('新北市','scooter','["paidMotorcycle", "freeMotorcycle"]'::jsonb,'["offStreet"]'::jsonb,'請依現場收費公告','請以現場標誌標線及場站規定為準；試辦路段須確認公告範圍。','2026-10-11','https://www.traffic.ntpc.gov.tw/home.jsp?act=be4f48068b2b0031&dataserno=99345bcf365b8f6ed7a6315705335638&id=54fa46e9e522dde4&mserno=39e5192ff77897e0ae099c1886ca9b09',1,false,'[]'::jsonb) on conflict(city,vehicle) do nothing;
insert into public.city_rules(city,vehicle,allowed_space_types,conditional_space_types,fee_note,exceptions,effective_date,source_url,version,can_use_two_spaces,districts) values('新北市','heavy','["heavyOnly", "car", "paidMotorcycle"]'::jsonb,'["offStreet"]'::jsonb,'收費機車格比照大型重機專用格，計次每 4 小時 30 元','2026/7/1 起全市路邊收費機車格開放大型重機；路邊免費機車格不開放。車身不得超出格線，車身較長可跨 2 格停放，仍須完全位於格線內。','2026-07-01','https://www.ntpc.gov.tw/ch/home.jsp?id=28&dataserno=202601150009',2,true,'[]'::jsonb) on conflict(city,vehicle) do nothing;
insert into public.city_rules(city,vehicle,allowed_space_types,conditional_space_types,fee_note,exceptions,effective_date,source_url,version,can_use_two_spaces,districts) values('桃園市','scooter','["paidMotorcycle", "freeMotorcycle"]'::jsonb,'["offStreet"]'::jsonb,'請依現場收費公告','請以現場標誌標線及場站規定為準；試辦路段須確認公告範圍。','2026-10-11','https://www.tycg.gov.tw/NewsPage_Content.aspx?n=7&s=1612945&sms=7882',1,false,'[]'::jsonb) on conflict(city,vehicle) do nothing;
insert into public.city_rules(city,vehicle,allowed_space_types,conditional_space_types,fee_note,exceptions,effective_date,source_url,version,can_use_two_spaces,districts) values('桃園市','heavy','["heavyOnly", "car", "paidMotorcycle", "freeMotorcycle"]'::jsonb,'["offStreet"]'::jsonb,'比照普通機車，依各路段費率與時段','2026/4/1 起試辦全市路邊機車格（收費與不收費）開放大型重機。以一車一格為原則，車身較長可斜停最多 2 格，車體須完全位於格線內。','2026-04-01','https://www.tycg.gov.tw/NewsPage_Content.aspx?n=7&s=1612945&sms=7882',2,true,'[]'::jsonb) on conflict(city,vehicle) do nothing;
insert into public.city_rules(city,vehicle,allowed_space_types,conditional_space_types,fee_note,exceptions,effective_date,source_url,version,can_use_two_spaces,districts) values('臺中市','scooter','["paidMotorcycle", "freeMotorcycle"]'::jsonb,'["offStreet"]'::jsonb,'請依現場收費公告','請以現場標誌標線及場站規定為準；試辦路段須確認公告範圍。','2026-10-11','https://tcparking.taichung.gov.tw/ParkWebStage/Pages/PublicService/Heavybike',1,false,'[]'::jsonb) on conflict(city,vehicle) do nothing;
insert into public.city_rules(city,vehicle,allowed_space_types,conditional_space_types,fee_note,exceptions,effective_date,source_url,version,can_use_two_spaces,districts,restriction) values('臺中市','heavy','["heavyOnly", "car"]'::jsonb,'["offStreet", "paidMotorcycle", "freeMotorcycle"]'::jsonb,'比照一般機車費率，依區域與路段計收','2026/5/1 起於逢甲、勤美、文心秀泰及台中火車站周邊試辦，僅限地面標示「大重機共用」的路邊機車格與機慢車停放區。須依格線停放、不得出線；車身過大請改停汽車格。','2026-05-01','https://www.traffic.taichung.gov.tw/news/index-1.asp?Parser=9%2C4%2C20%2C%2C%2C%2C21267',2,false,'[]'::jsonb,'signage') on conflict(city,vehicle) do nothing;
