insert into public.city_rules(city,vehicle,allowed_space_types,conditional_space_types,fee_note,exceptions,effective_date,source_url,version,can_use_two_spaces,districts) values('高雄市','heavy','["heavyOnly", "car"]'::jsonb,'["offStreet"]'::jsonb,'請依現場收費公告','路邊機車格未開放大型重機，請停汽車格或重機專用格。2026/8/1 起僅於 5 處捷運周邊公有停車場試辦停放普通機車格，請依場站公告。','2026-08-01','https://www.facebook.com/tbkcdream/posts/1370509398601080/',2,false,'[]'::jsonb) on conflict(city,vehicle) do nothing;
